#!/usr/bin/env python3
"""Materialize TLS fuzz seed corpora from in-repo hex (no .bin in git).

Run: python3 test/fuzz_corpus/generate_seeds.py
Idempotent; writes test/fuzz_corpus/tls_der/*.bin and tls_hs/*.bin
(gitignored). Harnesses call this before libFuzzer.
"""
