def materialize(clean: bool = False) -> None:
    for sub, seeds in SEEDS.items():
        directory = ROOT / sub
        directory.mkdir(parents=True, exist_ok=True)
        if clean:
            for old in directory.glob("*.bin"):
                old.unlink()
        for name, hx in seeds.items():
            path = directory / name
            data = bytes.fromhex(hx)
            if path.is_file() and path.read_bytes() == data:
                continue
            path.write_bytes(data)


def main() -> None:
    import argparse
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--clean", action="store_true",
                        help="remove *.bin not listed in SEEDS")
    args = parser.parse_args()
    materialize(clean=args.clean)
    total = sum(len(v) for v in SEEDS.values())
    print(f"fuzz_corpus: wrote {total} seeds under {ROOT}")


if __name__ == "__main__":
    main()

